/* A STATUS frame's flags, bit by bit as on the wire (and a timeline's expected flags). */
#define EXP_CASE_FLAG_EVENT 0x01u
#define EXP_CASE_FLAG_MORE 0x02u
#define EXP_CASE_FLAG_OVERFLOW 0x04u
#define EXP_CASE_FLAG_SUPPLY_OK 0x08u
#define EXP_CASE_FLAG_LEASE_EXPIRED 0x10u
#define EXP_CASE_FLAG_FRESH 0x20u
#define EXP_CASE_FLAG_CMD_ERROR 0x40u

/* A COMMAND's fields: op 1-8 (ACK ... CONFIG), mode 0 off 1 on 2 pattern, parameter 1-3. */
typedef struct {
    uint8_t op, seq, armed, channel, mode;
    uint16_t duration_100ms, on_10ms, off_10ms;
    uint8_t lease_100ms, seconds, parameter;
    uint16_t value;
} exp_cmd_case_t;

/* reason NULL: the box takes the frame, with these fields. */
typedef struct {
    const char *name;
    const uint8_t *bytes;
    size_t len;
    const char *reason;
    const char *module;
    bool inputs, outputs;
    uint8_t channels;
    uint16_t model;
    const char *model_name;
    uint8_t hw;
    uint8_t fw[3];
    uint8_t uid[4];
} exp_ident_case_t;

typedef struct {
    const char *name;
    int index; /* the index the box asked for */
    const uint8_t *bytes;
    size_t len;
    const char *reason;
    const char *module;
    uint8_t kind; /* 0x01 hit, 0x10 output */
    bool relay, solid_state, senses_supply;
    uint8_t hint; /* 0 generic ... 5 horn */
    uint8_t max_on_s, min_off_s;
} exp_channel_case_t;

typedef struct {
    const char *name;
    const char *module;
    int channels;
    const uint8_t *bytes;
    size_t len;
    const char *reason;
    bool event;
    uint8_t seq, channel, kind, value;
    uint16_t age_ms;
    uint8_t flags; /* EXP_CASE_FLAG_*, without EVENT */
    uint8_t outputs, armed;
    int32_t t_read_ms, t_event_ms; /* -1 when the case has none */
} exp_status_case_t;

/* A write after the address byte; reason NULL: the module at `address` takes it. */
typedef struct {
    const char *name;
    const char *module;
    int address;
    const uint8_t *bytes;
    size_t len;
    const char *reason;
    exp_cmd_case_t fields;
} exp_command_case_t;

typedef struct {
    const char *name;
    int address;
    const uint8_t *ident;
    int channels;
    const uint8_t *channel[8];
} exp_module_case_t;

typedef struct {
    int32_t t_ms;
    bool write;
    exp_cmd_case_t fields;
    const uint8_t *bytes;
    size_t len;
    bool delivered; /* false: lost on the cable, the module never sees it */
    int accepted;   /* 1 taken, 0 refused, -1 not delivered */
    bool restart;   /* the module restarts at t_ms */
    bool expect;
    uint8_t outputs, flags; /* flags: lease_expired, fresh, cmd_error */
} exp_step_case_t;

typedef struct {
    const char *name;
    const char *module;
    const exp_step_case_t *steps;
    size_t count;
} exp_timeline_case_t;

